import{_ as a,o as i,c as t,an as s}from"./chunks/framework.CAdatUIw.js";const d=JSON.parse('{"title":"Signal Example — Central Limit Theorem (CLT)","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/teaching/ica/signal_example_ica_clt.md","filePath":"tutorials/teaching/ica/signal_example_ica_clt.md","lastUpdated":null}'),o={name:"tutorials/teaching/ica/signal_example_ica_clt.md"};function l(n,e,r,h,u,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="Signal-Example-—-Central-Limit-Theorem-CLT" tabindex="-1">Signal Example — Central Limit Theorem (CLT) <a class="header-anchor" href="#Signal-Example-—-Central-Limit-Theorem-CLT" aria-label="Permalink to &quot;Signal Example — Central Limit Theorem (CLT) {#Signal-Example-—-Central-Limit-Theorem-CLT}&quot;">​</a></h1><p>Before jumping into the heavy geometry and optimization algorithms of ICA, we need to answer a fundamental question: <strong>How does an algorithm mathematically know when it has successfully unmixed a signal?</strong></p><div class="tip custom-block github-alert"><p class="custom-block-title">This demo bridges the gap between the concept of mixtures and the objective function the ICA algorithm uses to untangle them.</p><p></p></div><h2 id="The-Central-Limit-Theorem-in-EEG" tabindex="-1">The Central Limit Theorem in EEG <a class="header-anchor" href="#The-Central-Limit-Theorem-in-EEG" aria-label="Permalink to &quot;The Central Limit Theorem in EEG {#The-Central-Limit-Theorem-in-EEG}&quot;">​</a></h2><p>The Central Limit Theorem (CLT) states that if you take multiple independent variables and add them together, the distribution of their <em>sum</em> will always be <strong>more Gaussian</strong> (more like a normal bell-curve) than any of the original variables.</p><p>Brain sources (like a blink artifact, a heart beat, or a rigid alpha burst) are usually highly structured, repeating events. Statistically, they are very &quot;pointy&quot; (Super-Gaussian) or very &quot;flat&quot; (Sub-Gaussian). They do not look like perfect bell curves.</p><p>However, because a scalp electrode records a huge volume-conducted mixture of hundreds of these independent brain, muscle, and eye sources, it effectively sums them all up. Because of the CLT, the resulting EEG signal on your screen looks incredibly Gaussian!</p><h2 id="The-Core-Logic-of-ICA" tabindex="-1">The Core Logic of ICA <a class="header-anchor" href="#The-Core-Logic-of-ICA" aria-label="Permalink to &quot;The Core Logic of ICA {#The-Core-Logic-of-ICA}&quot;">​</a></h2><p>Because of the Central Limit Theorem, ICA algorithms operate on one beautifully simple reverse rule: <strong>Mixtures are Gaussian. True sources are not.</strong></p><p>If an algorithm wants to find a pure brain source, all it has to do is computationally rotate the data backwards until the resulting distribution stops looking like a bell curve! This is why you will hear the phrase &quot;ICA maximizes Non-Gaussianity&quot; or &quot;ICA maximizes Kurtosis&quot;.</p><h2 id="The-Interactive-Sandbox" tabindex="-1">The Interactive Sandbox <a class="header-anchor" href="#The-Interactive-Sandbox" aria-label="Permalink to &quot;The Interactive Sandbox {#The-Interactive-Sandbox}&quot;">​</a></h2><p>This demonstration is the purest possible physical proof of the Central Limit Theorem.</p><ul><li><p>It initializes a single flat distribution (Sub-Gaussian, Kurtosis = -1.20).</p></li><li><p>The slider lets you physically add more independent flat distributions together.</p></li><li><p>Adding just 2 shapes forms a triangle.</p></li><li><p>Adding 5+ shapes instantly forces the histogram perfectly into a mathematically smooth Gaussian Bell Curve (kurtosis dropping to 0.0).</p></li></ul><p>This conclusively proves the statistical behavior that makes Blind Source Separation possible.</p><h2 id="Code" tabindex="-1">Code <a class="header-anchor" href="#Code" aria-label="Permalink to &quot;Code {#Code}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EegFun</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">signal_example_ica_clt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>`,16)])])}const m=a(o,[["render",l]]);export{d as __pageData,m as default};
